/// Assumes, without verification, that a buffer of bytes contains a size prefixed GNP and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `GNP`.
pub unsafe fn size_prefixed_root_as_gnp_unchecked(buf: &[u8]) -> GNP<'_> {
  unsafe { ::flatbuffers::size_prefixed_root_unchecked::<GNP>(buf) }
}
pub const GNP_IDENTIFIER: &str = "$GNP";

#[inline]
pub fn gnp_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, GNP_IDENTIFIER, false)
}

#[inline]
pub fn gnp_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, GNP_IDENTIFIER, true)
}

#[inline]
pub fn finish_gnp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<GNP<'a>>) {
  fbb.finish(root, Some(GNP_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_gnp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>, root: ::flatbuffers::WIPOffset<GNP<'a>>) {
  fbb.finish_size_prefixed(root, Some(GNP_IDENTIFIER));
}
